Algorithm AHOGS+LD(problem_spec, time_limit, seed)
  // Adaptive Hierarchical Operator-Guided Search with Learned Dynamics (task-agnostic)
  Init hooks: ENCODE, DECODE, COST, VALIDATE, REPAIR, OPERATORS, DECOMPOSE
  operator_pool := OPERATORS; bandit := init_contextual_bandit(operator_pool)
  surrogate := init_surrogate(problem_spec); context_model := init_context_model()
  population := seed_population(problem_spec, seed, heuristics + random); elite := {}
  for s in population: s := REPAIR(s); s.cost := COST(s); if VALIDATE(s) add(elite,s)
  while not stop(time_limit, iteration, stagnation):
    subproblems := DECOMPOSE(population, elite, context_model)
    for sub in select_focus(subproblems, budget):
      parent := select_parent(population, elite, fitness+novelty)
      op := bandit.select(context=sub); child := APPLY_OPERATOR(parent, op, context=sub)
      child := REPAIR_IF_INVALID(child); child := LOCAL_INTENSIFY(child, sub, OPERATORS.local_search)
      child.cost := HYBRID_EVAL(child, COST, surrogate); reward := credit_function(child,parent,feasibility,novelty)
      bandit.update(op, context=sub, reward); population := replacement(population, child, strategy=age_diversity)
      update(elite, child)
    if periodic_recombine(): population := recombine(elite, OPERATORS.recombine, context_model)
    adapt_surrogate_and_context(surrogate, context_model, elite, history)
    if restart_condition(): population := strategic_restart(elite, seed_variation)
  return best(elite)

